BEGIN;
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS demo_label TEXT;
ALTER TABLE brand_profiles ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS demo_label TEXT;
ALTER TABLE generated_content ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS demo_label TEXT, ADD COLUMN IF NOT EXISTS input JSONB, ADD COLUMN IF NOT EXISTS provider_receipt JSONB, ADD COLUMN IF NOT EXISTS model TEXT;
ALTER TABLE ab_tests ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS demo_label TEXT, ADD COLUMN IF NOT EXISTS input JSONB;
CREATE TABLE IF NOT EXISTS operational_drafts(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,task TEXT NOT NULL,owner TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN('low','medium','high')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','in_progress','review_needed','closed')),is_demo BOOLEAN NOT NULL DEFAULT FALSE,demo_label TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS operational_drafts_user_idx ON operational_drafts(user_id,id);
COMMIT;
